        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      }
    },
    {
      "id": "getCurrentWeather1",
      "type": "uipath.connector.custom-codereval-openmeteoapis.getcurrentweather",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Get Current Weather"
      },
      "inputs": {
        "errorHandlingEnabled": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the connector.",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "evaluateWeather1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate Weather"
      },
      "inputs": {
        "script": "const cw = $vars.getCurrentWeather1.output.current_weather;\nconst temp = cw ? cw.temperature : null;\nconst windspeed = cw ? cw.windspeed : null;\nconst weatherCode = cw ? cw.weathercode : null;\n\n// Nice day: at least 15C, clear or partly cloudy (code 0-3), wind under 30 km/h\nconst isNice = temp !== null && temp >= 15 && weatherCode !== null && weatherCode <= 3 && windspeed !== null && windspeed < 30;\nconst tempF = temp !== null ? Math.round(temp * 9 / 5 + 32) : null;\n\nlet description = 'unknown';\nif (weatherCode !== null) {\n  if (weatherCode === 0) description = 'clear skies';\n  else if (weatherCode <= 3) description = 'partly cloudy';\n  else if (weatherCode <= 48) description = 'foggy';\n  else if (weatherCode <= 67) description = 'rainy';\n  else if (weatherCode <= 77) description = 'snowy';\n  else if (weatherCode <= 82) description = 'showery';\n  else description = 'stormy';\n}\n\nconst message = isNice\n  ? 'Yes! It\\'s a nice day in Bellevue! ' + tempF + '\\u00b0F (' + temp + '\\u00b0C), ' + description + ', wind ' + windspeed + ' km/h.'\n  : 'Not a great day in Bellevue. ' + tempF + '\\u00b0F (' + temp + '\\u00b0C), ' + description + ', wind ' + windspeed + ' km/h.';\n\nreturn { isNice: isNice, temperature: temp, windspeed: windspeed, weatherCode: weatherCode, message: message };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "isNiceDay1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Is it a nice day?"
      },
      "inputs": {
        "expression": "$vars.evaluateWeather1.output.isNice === true",
        "trueLabel": "Nice day",
        "falseLabel": "Not so nice"
      },
      "outputs": {
        "matchedCase": {
          "type": "string",
          "description": "The label of the matched branch (true/false label)",
          "var": "matchedCase"
        },
        "matchedCaseId": {
          "type": "string",
          "description": "The branch that was taken (true or false)",
          "var": "matchedCaseId"
        }
      }
    },
    {
      "id": "endNice",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Nice Day"
      },
      "inputs": {}
    },
    {
      "id": "endNotNice",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Not Nice Day"
      },
      "inputs": {}
    },
    {
      "id": "handleError1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Handle Error"
      },
      "inputs": {
        "script": "const err = $vars.getCurrentWeather1.error;\nconst message = err ? ('Could not fetch weather data: ' + (err.message || JSON.stringify(err))) : 'Could not fetch weather data: unknown error';\nreturn { message: message };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endError",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Error End"
      },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "e-start-getCurrentWeather1",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "getCurrentWeather1",
      "targetPort": "input"
    },
    {
      "id": "e-getCurrentWeather1-evaluateWeather1",
      "sourceNodeId": "getCurrentWeather1",
      "sourcePort": "output",
      "targetNodeId": "evaluateWeather1",
      "targetPort": "input"
    },
    {
      "id": "e-getCurrentWeather1-handleError1",
      "sourceNodeId": "getCurrentWeather1",
      "sourcePort": "error",
      "targetNodeId": "handleError1",
      "targetPort": "input"
    },
    {
      "id": "e-evaluateWeather1-isNiceDay1",
      "sourceNodeId": "evaluateWeather1",
